html:
{#- BOQ Quotation (catalogue 2.7): the client's bill, priced, grouped by cost head
    with subtotals, preliminaries first; then a summary page with the totals,
    validity and exclusions. Selling figures only. -#}
{%- set ns = namespace(total=0) -%}
{%- set heads = {} -%}
{%- set contingency = doc.items | selectattr("is_contingency") | list -%}
{%- for row in doc.items if not row.is_contingency -%}
	{%- set key = row.cost_head or "" -%}
	{%- if key not in heads -%}{%- set _ = heads.update({key: []}) -%}{%- endif -%}
	{%- set _ = heads[key].append(row) -%}
{%- endfor -%}
{%- set prelim_heads = frappe.get_all("Cost Head", filters={"is_preliminaries": 1}, pluck="name") -%}
{%- set order = (heads.keys() | select("in", prelim_heads) | list) + (heads.keys() | reject("in", prelim_heads) | list) -%}
{%- set title = frappe.db.get_value("Opportunity", doc.opportunity, "title") if doc.opportunity else "" -%}
{%- macro head_name(key) -%}{{ frappe.db.get_value("Cost Head", key, "cost_head_name") or key or _("Other work") }}{%- endmacro -%}
{%- macro money(v) -%}{{ frappe.utils.fmt_money(v, currency=doc.currency) }}{%- endmacro -%}

<style>
	.boq-quote { font-size: 9pt; }
	.boq-quote h2 { margin: 0 0 2px; }
	.boq-quote .meta { width: 100%; margin: 8px 0 14px; }
	.boq-quote .meta td { padding: 2px 8px 2px 0; vertical-align: top; }
	.boq-quote .label { color: #666; }
	.boq-quote .num { text-align: right; white-space: nowrap; }
	.boq-quote .head-row td { background: #f3f4f2; font-weight: bold; }
	.boq-quote .sub-row td { font-style: italic; }
	.boq-quote .total-row td { font-weight: bold; border-top: 2px solid #333; }
</style>

<div class="boq-quote">
	<h2>{{ _("Quotation") }} {{ doc.name }}</h2>
	<div style="color: #555;">{{ title or "" }}{% if doc.revision_no %} · {{ _("Revision {0}").format(doc.revision_no) }}{% endif %}</div>
	<table class="meta">
		<tr>
			<td style="width: 50%;"><span class="label">{{ _("To") }}</span><br><b>{{ doc.customer_name or doc.party_name }}</b>
				{%- if doc.address_display %}<br>{{ doc.address_display }}{% endif %}</td>
			<td><span class="label">{{ _("Date") }}</span><br>{{ frappe.utils.formatdate(doc.transaction_date) }}</td>
			<td><span class="label">{{ _("Valid until") }}</span><br>{{ frappe.utils.formatdate(doc.valid_till) if doc.valid_till else "" }}</td>
			<td><span class="label">{{ _("Currency") }}</span><br>{{ doc.currency }}</td>
		</tr>
	</table>

	<table class="table table-bordered table-condensed">
		<thead>
			<tr>
				<th style="width: 9%;">{{ _("Ref") }}</th>
				<th>{{ _("Description") }}</th>
				<th style="width: 9%;">{{ _("Unit") }}</th>
				<th class="num" style="width: 10%;">{{ _("Qty") }}</th>
				<th class="num" style="width: 12%;">{{ _("Rate") }}</th>
				<th class="num" style="width: 15%;">{{ _("Amount") }}</th>
			</tr>
		</thead>
		<tbody>
		{%- set sections = [] -%}
		{%- for key in order -%}
			{%- set ns.head = 0 -%}
			<tr class="head-row"><td colspan="6">{{ head_name(key) }}</td></tr>
			{%- for row in heads[key] -%}
				<tr>
					<td>{{ row.boq_ref or row.idx }}</td>
					<td>{{ row.description or row.item_name }}</td>
					<td>{{ row.uom or "" }}</td>
					<td class="num">{{ frappe.utils.fmt_money(row.qty, precision=(3 if (row.qty or 0) % 1 else 0)) }}</td>
					<td class="num">{{ money(row.rate) }}</td>
					<td class="num">{{ money(row.amount) }}</td>
				</tr>
				{%- set ns.head = ns.head + (row.amount or 0) -%}
			{%- endfor -%}
			<tr class="sub-row"><td colspan="5" class="num">{{ _("Total") }}, {{ head_name(key) }}</td><td class="num"><b>{{ money(ns.head) }}</b></td></tr>
			{%- set _ = sections.append((head_name(key), ns.head)) -%}
		{%- endfor -%}
		{%- for row in contingency -%}
			<tr class="head-row"><td colspan="6">{{ _("Contingency") }}</td></tr>
			<tr><td>{{ row.boq_ref or "" }}</td><td colspan="4">{{ row.description or _("Contingency") }}</td><td class="num">{{ money(row.amount) }}</td></tr>
		{%- endfor -%}
		</tbody>
	</table>

	<div class="page-break"></div>

	<h3 style="margin-top: 0;">{{ _("Summary") }}</h3>
	<table class="table table-bordered table-condensed">
		<tbody>
		{%- for name, amount in sections -%}
			<tr><td>{{ name }}</td><td class="num" style="width: 22%;">{{ money(amount) }}</td></tr>
		{%- endfor -%}
		{%- for row in contingency -%}
			<tr><td>{{ _("Contingency") }}</td><td class="num">{{ money(row.amount) }}</td></tr>
		{%- endfor -%}
		{%- if doc.discount_amount -%}
			<tr><td>{{ _("Discount") }}</td><td class="num">− {{ money(doc.discount_amount) }}</td></tr>
		{%- endif -%}
			<tr class="total-row"><td>{{ _("Total before tax") }}</td><td class="num">{{ money(doc.net_total) }}</td></tr>
		{%- for tax in doc.taxes if tax.tax_amount -%}
			<tr><td>{{ tax.description }}</td><td class="num">{{ money(tax.tax_amount) }}</td></tr>
		{%- endfor -%}
			<tr class="total-row"><td>{{ _("Quotation Total") }}</td><td class="num">{{ money(doc.grand_total) }}</td></tr>
		</tbody>
	</table>
	{%- if doc.in_words %}<p><span class="label">{{ _("In words") }}:</span> {{ doc.in_words }}</p>{% endif %}

	<h4>{{ _("Validity") }}</h4>
	<p>{% if doc.valid_till -%}
		{{ _("This quotation is valid until {0}. After that date the rates are subject to review.").format(frappe.utils.formatdate(doc.valid_till)) }}
	{%- else -%}{{ _("The rates are subject to review if the work is not awarded within 30 days.") }}{%- endif %}</p>

	{%- if doc.exclusions %}
	<h4>{{ _("Exclusions") }}</h4>
	<ul>{% for line in doc.exclusions.splitlines() if line.strip() %}<li>{{ line.strip().lstrip("-•* ") }}</li>{% endfor %}</ul>
	{%- endif %}

	{%- if doc.terms %}
	<h4>{{ _("Terms") }}</h4>
	<div>{{ doc.terms }}</div>
	{%- endif %}
</div>
